import * as d3 from "d3";
const svg=d3.select("body").append("svg").attr("width",320).attr("height",200).attr("viewBox","0 0 320 200");
const x=d3.scaleLinear().domain([0,100]).range([20,300]);
svg.append("circle").attr("cx",x(50)).attr("cy",80).attr("r",8);

import * as d3 from "d3";
const svg=d3.select("body").append("svg").attr("width",320).attr("height",200).attr("viewBox","0 0 320 200");
const x=d3.scaleBand().domain(["Mon","Tue","Wed"]).range([20,300]).padding(0.2);
svg.selectAll("rect").data(["Mon","Tue","Wed"]).join("rect").attr("x",d=>x(d)).attr("y",50).attr("width",x.bandwidth()).attr("height",80).attr("fill","navy");

import * as d3 from "d3";
const svg=d3.select("body").append("svg").attr("width",320).attr("height",200).attr("viewBox","0 0 320 200");
const values=[30,60,90];
const y=d3.scaleLinear().domain([0,100]).range([180,20]);
svg.selectAll("rect").data(values).join("rect").attr("x",(_d,i)=>30+i*90).attr("width",50).attr("y",d=>y(d)).attr("height",d=>180-y(d)).attr("fill","teal");

import * as d3 from "d3";
