import * as d3 from "d3";
const svg=d3.select("body").append("svg").attr("width",320).attr("height",200).attr("viewBox","0 0 320 200");
const pie=d3.pie()([2,3,5]);const arc=d3.arc().innerRadius(0).outerRadius(70);
